export type Draft = {
  key: string;
  item: string;
  line: number;
  text?: string;
  thread?: string;
  range?: { start: number; end: number; quote: string };
  body?: string;
  suggestion?: string;
};
export type Stale = Draft & { revision: number; answer?: { choice: string; title?: string; label?: string } };
export type Drafts = {
  revision?: number;
  pending?: Draft[];
  answers?: Record<string, string>;
  labels?: Record<string, { title?: string; label?: string }>;
  resolved?: string[];
  summary?: string;
  composer?: (Draft & Record<string, unknown>) | null;
  stale?: Stale[];
  kept?: (Omit<Draft, "key"> & Record<string, unknown>)[];
};
export type Now = {
  revision: number;
  lineAt(item: string, line: number): string | undefined;
  linesOf(item: string): string[] | undefined;
  choiceLabel(item: string, choice: string): string | undefined;
};
export function readDrafts(id: string): Drafts | undefined;
export function writeDrafts(id: string, drafts: Drafts & { at?: string }): boolean;
export function asStale<T extends Record<string, unknown>>(c: T): T;
export function rebase(drafts: Drafts, now: Now): Required<Omit<Drafts, "composer">> & { composer: Drafts["composer"] };
export function readKept<T = unknown>(name: string): T | undefined;
export function keep(name: string, value: unknown): boolean;
export function keptNames(prefix: string): string[];
export function dropKept(id: string, opts?: { build?: boolean; ask?: boolean; review?: boolean }): void;
export function sweepKept(list: { id: string; closed?: unknown; superseded_by?: string; status_key?: string; build?: string; ask?: unknown }[]): void;
export function keepSoon(name: string, write: () => boolean, box?: HTMLInputElement | HTMLTextAreaElement): void;
export function cancelSoon(name: string): void;
export function release(name: string): void;
export function holdKept<T = unknown>(name: string): T | undefined;
export function dropNames(name: string): void;
export function staleDraftHtml(name: string, text: string, what: string): string;
export function staleName(name: string): string;
export function parkStale<T = unknown>(name: string, isStale: (kept: T & Record<string, unknown>) => boolean): T | undefined;
export const SAVED_SLOT: string;
